#include <Arduino.h>

void setup();
void loop();
void setup() {
  pinMode(2, OUTPUT);
  pinMode(3, OUTPUT);
}
void loop() {
  digitalWrite(2, LOW);
  digitalWrite(3, LOW);
  delay(5000);
  digitalWrite(2, HIGH);
  delay(5000);
  digitalWrite(3, HIGH);
  delay(5000);
  digitalWrite(2, LOW);
  digitalWrite(3, LOW);
  delay(5000);
}
